import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.gtmkOXzY.js";const m=JSON.parse('{"title":"Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/requirements.md","filePath":"ms-flightsim/requirements.md","lastUpdated":null}'),a={name:"ms-flightsim/requirements.md"};function i(n,t,c,l,s,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h1><p>You need a OneSync server on game build 2699 or newer, oxmysql and ox_lib. Everything else is optional and detected automatically.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Needed?</th><th>Notes</th></tr></thead><tbody><tr><td>OneSync</td><td>Required</td><td>Entity lockdown <code>relaxed</code> or <code>inactive</code> recommended</td></tr><tr><td>Game build 2699+</td><td>Required</td><td><code>sv_enforceGameBuild 2699</code> or higher</td></tr><tr><td>oxmysql</td><td>Required</td><td>MySQL or MariaDB database</td></tr><tr><td>ox_lib</td><td>Required</td><td></td></tr><tr><td>Framework</td><td>Required</td><td>QBox (<code>qbx_core</code>), QBCore (<code>qb-core</code>) or ESX (<code>es_extended</code>), auto-detected</td></tr><tr><td>ox_target</td><td>Optional</td><td>Without it, NPCs use an <code>[E]</code> prompt</td></tr><tr><td>ox_inventory</td><td>Optional</td><td>On QBCore/QBox, smuggling pays black money as an item with it; without it, to the dirty-money account (<code>Config.QBDirtyMoneyAccount</code>, default <code>cash</code>). ESX always uses the <code>black_money</code> account</td></tr><tr><td>Vehicle keys</td><td>Optional</td><td>Keys are given automatically with qbx_vehiclekeys, qb-vehiclekeys, Renewed-Vehiclekeys, wasabi_carlock, okokGarage, jaksam vehicle keys and MrNewbVehicleKeys</td></tr><tr><td>Fuel script</td><td>Optional</td><td>LegacyFuel, ox_fuel, ps-fuel, lc_fuel, cdn-fuel, ti_fuel, ND_Fuel, Renewed-Fuel, BigDaddy-Fuel</td></tr><tr><td>Billing</td><td>Optional</td><td>esx_addonaccount + esx_billing — to back the company fund</td></tr><tr><td>City hall</td><td>Optional</td><td>qbx_cityhall, qb-cityhall, esx_cityhall — for physical licences</td></tr><tr><td>Dispatch</td><td>Optional</td><td>ps-dispatch</td></tr></tbody></table><h2 id="companion-resources" tabindex="-1">Companion resources <a class="header-anchor" href="#companion-resources" aria-label="Permalink to &quot;Companion resources&quot;">​</a></h2><p>All optional: MS_FlightSim runs without them, and the features that need one switch off.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Adds</th></tr></thead><tbody><tr><td><code>ms100</code></td><td>The MS-100 airliner (5 liveries), flown by the AI traffic</td></tr><tr><td><code>MS_FlightSim_MSE</code></td><td>The ground fleet (8 vehicles, 3 trailers) used by the ground-services job</td></tr><tr><td><code>MS_FlightSim_LSIA</code></td><td>The LSIA airport map. Do not run another LSIA map alongside it</td></tr><tr><td><code>ms_aircraft_core</code> (1.8.0+) + <code>ms41s</code></td><td>The Aerial Firefighting job and the MS41s on Offshore Supply</td></tr></tbody></table>',6)])])}const _=e(a,[["render",i]]);export{m as __pageData,_ as default};
